import csv
import io


def parse_csv(raw_csv: str):
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    records = list(csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=";",
        quotechar='"',
        doublequote=True,
        strict=False,
    ))

    expected_width = 4
    header_index = next(
        (i for i, record in enumerate(records)
         if len(record) == expected_width and any(field.strip() for field in record)),
        None,
    )
    if header_index is None:
        header_index = next(
            (i for i, record in enumerate(records)
             if any(field.strip() for field in record)),
            None,
        )
    if header_index is None:
        return {"columns": [], "rows": []}

    columns = records[header_index][:]
    rows = records[header_index + 1:]
    width = max(len(columns), max(map(len, rows), default=0))

    # Add columns for surplus fields rather than dropping or merging them.
    used_names = set(columns)
    for position in range(len(columns) + 1, width + 1):
        base = f"extra_{position}"
        name = base
        suffix = 2
        while name in used_names:
            name = f"{base}_{suffix}"
            suffix += 1
        columns.append(name)
        used_names.add(name)

    return {
        "columns": columns,
        "rows": [record + [""] * (width - len(record)) for record in rows],
    }
